def icon(name: str) -> str:
    return f'<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">{ICON_PATHS.get(name,ICON_PATHS["arrow"])}</svg>'
def ext(url: str, text: str, cls: str = '') -> str:
    return f'<a href="{E(url,quote=True)}" target="_blank" rel="noopener noreferrer" class="{cls}">{text}<span class="sr-only"> (opens in a new tab)</span></a>'
def clean_route(route: str) -> str:
    return route[:-10] if route.endswith('index.html') else route

class Page:
    def __init__(self, key: str, title: str, description: str, *, noindex: bool = False, mobile_cta: bool = False):
        self.key, self.path, self.title, self.description = key, PATHS[key], title, description
        self.noindex, self.mobile_cta = noindex, mobile_cta
        self.root = os.path.relpath(SITE, (SITE / self.path).parent).replace('\\','/') + '/'
        self.root = './' if self.root == './' else self.root
        self.body = ''
    def href(self, key: str, suffix: str = '') -> str:
        return self.root + PATHS.get(key,key) + suffix
    def link(self, key: str, text: str, cls: str = 'text-link', suffix: str = '', event: str = 'cta_click') -> str:
        return f'<a href="{E(self.href(key,suffix),quote=True)}" class="{cls}" data-event="{event}" data-target="{E(key)}">{text}</a>'
    def button(self, key: str, text: str, *, primary: bool = False, suffix: str = '', ico: str = 'arrow') -> str:
        return self.link(key, E(text)+' '+icon(ico), 'btn'+(' primary' if primary else ''), suffix)
    def asset(self, name: str) -> str:
        return self.root + 'assets/' + name
    def breadcrumbs(self, label: str) -> str:
        return f'<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="{self.href("home")}">PocketMic</a>{icon("chevron")}<span aria-current="page">{E(label)}</span></nav>'
    def hero(self, eyebrow: str, title: str, lede: str, actions: str = '', visual: str = '', label: str = '') -> str:
        content = f'{self.breadcrumbs(label or self.title)}<p class="eyebrow">{eyebrow}</p><h1>{title}</h1><p class="lede">{lede}</p>{actions}'
        return '<section class="page-hero"><div class="wrap">' + (f'<div class="page-hero-grid"><div>{content}</div>{visual}</div>' if visual else content) + '</div></section>'
    def source_note(self, extra: str = '') -> str:
        return f'<p class="source-note">Product baseline: {ext(RELEASE,"v0.1.4 release")} and {ext(README,"version-pinned project documentation")}, checked 9 September 2026. {extra}</p>'

PAGES: list[Page] = []
def page(*args, **kwargs) -> Page:
    p = Page(*args, **kwargs); PAGES.append(p); return p

def brand(p: Page) -> str:
    return f'<a class="brand" href="{p.href("home")}" aria-label="PocketMic LAN home"><span class="brand-mark">{icon("mic")}</span><span>PocketMic<span class="brand-sub">LAN</span></span></a>'
def stage(p: Page) -> str:
    bars=''.join(f'<i style="--h:{v}px"></i>' for v in [9,16,25,13,29,20,11,24,15,7])
    return f'''<figure class="product-stage" aria-label="PocketMic Android and Windows app screenshots">
<div class="stage-back" aria-hidden="true"></div><div class="stage-label">{icon('lock')} Your local connection</div>
<div class="stage-note"><strong>Two apps.<br>One audio path.</strong>Phone to Windows.</div>
<a class="image-link phone-frame" href="{p.asset('screenshots/android-app.webp')}" data-image-preview aria-label="Enlarge the Android app screenshot"><img src="{p.asset('screenshots/android-app-720.webp')}" width="720" height="1608" alt="PocketMic Android app with a masked pairing key, Voice mode, input gain, and Start button" fetchpriority="high" decoding="async"></a>
<a class="image-link receiver-frame" href="{p.asset('screenshots/windows-receiver.webp')}" data-image-preview aria-label="Enlarge the Windows receiver screenshot"><img src="{p.asset('screenshots/windows-receiver.webp')}" width="844" height="531" alt="PocketMic Windows receiver waiting for a phone, with CABLE Input audio routing" decoding="async"></a>
<div class="signal-pill"><div class="wave" aria-hidden="true">{bars}</div><span><strong>48 kHz audio</strong>Encrypted over your LAN</span></div>
<figcaption class="stage-caption">Real app captures · illustrative layout, not a live connection</figcaption></figure>'''
def footer(p: Page) -> str:
    groups = [
        ('Get started',[('downloads','Download both apps'),('setup','Setup guide'),('help','Troubleshooting')]),
        ('Find your setup',[('discord','Discord & gaming'),('obs','OBS & creators'),('meetings','Meetings & calls')]),
        ('Open by design',[('engineering','Technical details'),('release','Release notes'),('privacy','Privacy & terms')])
    ]
    cols=''.join(f'<div><h3>{title}</h3><div class="footer-links">'+''.join(p.link(k,t,'') for k,t in links)+'</div></div>' for title,links in groups)
    return f'''<footer class="footer"><div class="wrap"><div class="footer-grid"><div class="footer-brand">{brand(p)}<p>An Android microphone.<br>A Windows receiver.<br>Your own local connection.</p>{ext(REPO,icon('github')+' Source on GitHub','text-link')}</div>{cols}</div>
<div class="footer-bottom"><p>© 2026 Ryan Spice-Finnie · PocketMic software: MIT licensed</p><p>{ext('https://www.buymeacoffee.com/ryanspice','Support the project')} · No third-party tracking scripts in this site build.</p></div></div></footer>'''
def faq(items: list[tuple[str,str]]) -> str:
    return '<div class="faq">'+''.join(f'<details><summary>{q}</summary><div><p>{a}</p></div></details>' for q,a in items)+'</div>'
def final_cta(p: Page, heading: str = 'Put your phone<br>to work.', desc: str = 'Get both apps. Keep the connection local.') -> str:
    return f'<section class="section"><div class="wrap final-cta"><div><h2>{heading}</h2><p class="muted">{desc}</p></div><div class="btn-row">{p.button("downloads","Get the apps",primary=True)}{p.button("setup","Read the setup guide")}</div></div></section>'
def route_flow(target: str = 'Your app') -> str:
    return '<div class="flowline" aria-label="Audio routing"><b>Android</b>'+icon('arrow')+'<b>Windows receiver</b>'+icon('arrow')+'<b>VB-CABLE</b>'+icon('arrow')+f'<b>{E(target)}</b></div>'
def side_setup(p: Page, use: str = 'general') -> str:
    return f'''<aside><div class="side-card"><p class="eyebrow">Your setup</p><h2>Everything in one place.</h2><p>Android app + Windows receiver + VB-CABLE for microphone routing.</p>{p.button('downloads','Get both apps',primary=True,suffix='?use='+use)}<div class="btn-row">{p.link('setup','Follow the setup '+icon('arrow'),suffix='?use='+use)}</div><dl><dt>Platforms</dt><dd>Android 8+ · Windows 11 x64</dd><dt>Connection</dt><dd>Same trusted private network</dd><dt>Release</dt><dd>v0.1.4 · Early software</dd></dl></div></aside>'''
def official_download(url: str, label: str, target: str) -> str:
    return f'<a class="btn primary" href="{E(url,quote=True)}" data-event="download_click" data-target="{target}">{icon("down")}{E(label)}</a>'

