# -------------------------------- TROUBLESHOOTING
p=page('help','PocketMic troubleshooting: pairing, routing, no sound','Troubleshoot PocketMic in order: Android capture, LAN connection, Windows receiver, VB-CABLE route, then Discord, OBS, or your calling app.')
p.body=p.hero('Follow the signal','Find the break.<br><span class="accent">Not another workaround.</span>','Check the audio path in order. A phone meter, a receiver packet count, and an app input meter each answer a different question.',label='Troubleshooting')
issues=[
 ('pair','The phone will not connect.',f'<p>Check that both apps use the same release, both devices share a trusted private network, and the IP address, port, and pairing key match. QR pairing reduces manual entry errors.</p><p>Guest-network isolation, VPN routing, or a managed network may block device-to-device traffic. Check network configuration rather than disabling security tools. Use the project’s documented Private-network firewall rules.</p><p>{p.link("engineering","See the network and firewall notes.","",suffix="#network")}</p>'),
 ('meter','The phone’s input meter does not move.','<p>Confirm microphone permission is granted to PocketMic and the microphone is started. Check whether another app is using the microphone. Stop and restart capture, then test the available capture modes one at a time.</p><p>Do not interpret a successful QR scan as proof of microphone capture.</p>'),
 ('receiver','The phone meter moves, but receiver packets do not.','<p>Confirm the receiver is running and listening on the expected port. Recheck the PC address and pairing key. Review any receiver rejection messages. Return to the local-network and firewall checks if no packets arrive.</p>'),
 ('app','The receiver has audio, but my app hears nothing.',f'<p>Select <code>CABLE Input</code> as the receiver’s playback destination. In the destination app select <code>CABLE Output</code> as the microphone. If the endpoint was renamed, match the VB-CABLE playback and recording sides.</p><p>If the cable devices do not appear, finish the {ext(VB,"official VB-CABLE installation and restart steps")}. Reopen the destination app after the driver installation. Also check the app’s mute state and Windows microphone-access settings.</p>'),
 ('echo','I hear echo, doubling, or feedback.','<p>Turn off the receiver’s speaker-monitoring option when it is not needed. Use headphones for the listening output. In OBS, make sure the same audio device is not captured both globally and as a scene source.</p><p>Check one signal path at a time instead of stacking monitoring, loopback, and call playback.</p>'),
 ('delay','The sound is late, unstable, or cuts out.','<p>A 10 ms packet is not a 10 ms end-to-end path. Network conditions, device capture, receiver buffering, and Windows audio routing all contribute.</p><p>Test close to the access point and try a wired PC where practical. Observe loss and buffer diagnostics. Adjust the receiver prebuffer carefully: less buffering can reduce delay but leave less room for late packets. Review OBS sync in a recording rather than judging it from a moving meter.</p>'),
 ('install','The installation looks wrong or is blocked.',f'<p>Stop and confirm the exact source, file name, version, and checksum. The Android consumer download is the <strong>debug-signed APK</strong>, not the unsigned release artifact. The Windows receiver is a ZIP to extract, not an installer.</p><p>Do not disable Play Protect, antivirus, or the firewall to force installation. On a managed device, follow your organisation’s installation policy. {p.link("downloads","Return to verified download details.","")}</p>')]
p.body+=f'''<section class="page-section"><div class="wrap body-grid"><article><nav class="trouble-nav" aria-label="Troubleshooting symptoms">'''+''.join(f'<a href="#{id}">{label}</a>' for id,label in [('pair','Won’t connect'),('meter','No phone level'),('receiver','No packets'),('app','App hears nothing'),('echo','Echo'),('delay','Delay / dropouts'),('install','Install warning')])+'''</nav><div class="faq">'''+''.join(f'<details id="{id}" class="trouble-item"><summary>{title}</summary><div>{text}</div></details>' for id,title,text in issues)+f'''</div><div class="callout warning"><strong>Never fix routing with a public port.</strong><p>PocketMic is intended for a trusted private LAN. Do not expose the receiver to the internet or switch off the firewall.</p></div><h2>Still stuck?</h2><p>Report the app version, device models, destination app, symptom, and the last point in the signal path that worked. Remove pairing keys, QR codes, and sensitive connection details first.</p><div class="btn-row">{ext(REPO+'/issues','Read or open an issue '+icon('external'),'btn primary')}{p.button('setup','Back to setup')}</div>{p.source_note('Additional references: '+ext(VB,'VB-Audio')+', '+ext(OBS,'OBS audio sources')+', '+ext(DISCORD,'Discord mic testing')+'.')}</article>{side_setup(p)}</div></section>'''

# -------------------------------- TECHNICAL / DEVELOPER INTENT
p=page('engineering','PocketMic technical details and source','Inspect PocketMic’s Android-to-Windows audio path, authenticated encryption, buffering boundaries, capture modes, and version-pinned source builds.')
p.body=p.hero('For the curious. And the builders.','Local audio.<br><span class="accent">Open implementation.</span>','The product idea is simple: an Android microphone sends audio to a Windows receiver over a trusted private LAN. Here is what sits underneath — and what the specifications do not prove.',f'<div class="btn-row">{ext(SOURCE,"Read the pinned source "+icon("github"),"btn primary")}{p.button("downloads","Get the apps")}</div>',label='Technical details')
p.body+=f'''<section class="page-section"><div class="wrap body-grid"><article><h2>The audio path.</h2><p>Android captures 48,000 Hz mono PCM16. The sender places 480 samples into each 10 ms packet, encrypts the audio payload with AES-256-GCM, and sends it to the Windows receiver over UDP.</p><table class="spec-table"><caption class="sr-only">Documented PocketMic protocol values</caption><tbody><tr><th scope="row">Audio format</th><td>48 kHz · mono · signed PCM16 · little-endian</td></tr><tr><th scope="row">Packet duration</th><td>10 ms of captured audio</td></tr><tr><th scope="row">Audio per packet</th><td>480 samples / 960 plaintext bytes</td></tr><tr><th scope="row">Application datagram</th><td>24-byte header + 960-byte payload + 16-byte GCM tag = 1,000 bytes</td></tr><tr><th scope="row">Packet rate</th><td>100 packets per second</td></tr><tr><th scope="row">Audio payload rate</th><td>768 kbit/s</td></tr><tr><th scope="row">Datagram data rate</th><td>800 kbit/s, before UDP/IP and link-layer overhead</td></tr></tbody></table><p class="footnote">Rate calculation: 48,000 × 16 = 768,000 bits/s for mono audio; 1,000 × 100 × 8 = 800,000 bits/s for the application datagrams. These are protocol calculations, not measured network benchmarks.</p><h2 id="latency">A frame is not a benchmark.</h2><p>The documented receiver starts playback after a 100 ms default prebuffer and trims accumulated buffering above its high-water threshold. The prebuffer is adjustable; concealment and trimming are conservative rather than full adaptive jitter/clock recovery.</p><div class="callout"><strong>10 ms is the audio packet duration.</strong><p>It is not a measured phone-to-speaker or phone-to-app latency. The release notes leave end-to-end physical-device testing open. This website does not publish a universal delay, quality, range, or battery-life claim.</p></div><h2>Capture, without the overpromise.</h2><p><strong>Voice</strong> uses Android’s voice-communication source. <strong>Clean</strong> requests the least-processed supported input, with device-dependent fallbacks. Neither makes all phone microphones or vendor processing behave identically.</p><p>The supplied page also describes <strong>Custom</strong> mode with PC-side processing, and the supplied Android screenshot shows the selector. Check the actual release’s controls before relying on a particular DSP effect or live-control feature; the release README does not establish the full Custom-mode behaviour described by the page.</p><h2 id="network">Encryption and its boundary.</h2><table class="spec-table"><caption class="sr-only">Documented security and network details</caption><tbody><tr><th scope="row">Cipher</th><td>AES-256-GCM authenticated encryption</td></tr><tr><th scope="row">Pairing-key derivation</th><td><code>SHA-256(UTF-8(pairing key))</code></td></tr><tr><th scope="row">Nonce construction</th><td>Random 64-bit session ID + unsigned 32-bit sequence</td></tr><tr><th scope="row">Authenticated data</th><td>Complete 24-byte protocol header</td></tr><tr><th scope="row">Default audio port</th><td>UDP 49500</td></tr><tr><th scope="row">Control channel</th><td>The next port, per the project documentation. Use the project firewall helper rather than an audio-port-only assumption.</td></tr><tr><th scope="row">Intended environment</th><td>Trusted private LAN only</td></tr></tbody></table><p>Use the generated pairing material and treat the key and QR code as secrets. Encryption describes the transport design; it is not an independent security certification.</p><div class="callout warning"><strong>No internet exposure.</strong><p>Do not port-forward the receiver. A local encrypted transport is not a hardened internet voice service, and it does not control what your destination app does with the audio.</p></div><h2 id="build">Build from the pinned source.</h2><p>The tagged repository stores the project inside <code>pocketmic-lan-v0.1.4/</code>. Start there, not at the repository root. Build prerequisites documented for this version: Android SDK Platform 36, JDK 17+, and .NET 8 SDK.</p><pre><code>git clone --branch v0.1.4 --depth 1 {REPO}.git
Set-Location .\\pocketmic-lan\\pocketmic-lan-v0.1.4
.\\scripts\\build-android.ps1
.\\scripts\\publish-windows.ps1</code></pre><p>Review scripts before execution and follow your organisation’s PowerShell policy. These are the native app’s build commands, not requirements for hosting this static website.</p><h3>Firewall helper</h3><pre><code># From the native project directory, in elevated PowerShell:
.\\scripts\\allow-firewall.ps1</code></pre><p>Apply only to the trusted Private network profile. Inspect the helper for audio and control-channel rules rather than adding a broad allow-all exception.</p><h2>What is still a real-world test?</h2><div class="proof-grid"><div class="proof-card"><h3>Audio and timing</h3><p>Phone-to-app latency, capture quality, Wi-Fi stability, and audio-driver behaviour on the user’s hardware.</p></div><div class="proof-card"><h3>Install and support</h3><p>Debug-signed Android distribution, Windows security prompts, driver installation, and device-specific permissions.</p></div></div>{p.source_note('Protocol calculations are derived above. Custom-mode scope is explicitly separated from release-confirmed features. Source and build links are pinned so a later release does not silently change these instructions.')}</article><aside><div class="side-card"><p class="eyebrow">Under the hood</p><h2>Two native apps.</h2><dl><dt>Android</dt><dd>Kotlin · Jetpack Compose</dd><dt>Windows</dt><dd>C# · .NET 8 · WinForms · NAudio</dd><dt>Transport</dt><dd>Encrypted UDP on a private LAN</dd><dt>Virtual microphone</dt><dd>VB-CABLE, installed separately</dd><dt>Software licence</dt><dd>MIT</dd></dl><hr>{ext(SOURCE,'Browse the source '+icon('external'),'text-link')}<br><br>{p.link('release','Release details '+icon('arrow'))}</div></aside></div></section>'''

# -------------------------------- RELEASE NOTES
p=page('release','PocketMic v0.1.4 release details','PocketMic v0.1.4: exact Android and Windows release artifacts, signing status, checksums, QR pairing, and remaining device-testing boundaries.')
p.body=p.hero('Release notes / 9 September 2026','PocketMic<br><span class="accent">v0.1.4.</span>','The version used by this website. Release assets and notes were checked against the project’s GitHub release on 9 September 2026.',f'<div class="btn-row">{p.button("downloads","Get this release",primary=True)}{ext(REPO+"/releases","See all releases "+icon("external"),"btn")}</div>',label='Release notes')
p.body+=f'''<section class="page-section"><div class="wrap narrow"><div class="release-items"><article><h3>QR pairing</h3><p>The release notes describe QR pairing and the Windows receiver’s QR display, reducing manual entry of connection details.</p></article><article><h3>Pairing-key storage on Android</h3><p>The release adds encrypted Android storage for pairing keys. Keep the pairing key and QR code private regardless of how they are stored.</p></article><article><h3>Streaming and lifecycle work</h3><p>The release points to the changelog for its streaming and lifecycle fixes. This page does not reinterpret those implementation changes as a universal end-to-end performance benchmark.</p></article></div><h2 style="margin-top:45px;font-size:2rem">The actual release files.</h2><table class="spec-table"><caption class="sr-only">Published v0.1.4 artifacts</caption><tbody><tr><th scope="row">Android installation</th><td><code>PocketMic-v0.1.4-debug.apk</code><br>Installable, debug-signed APK</td></tr><tr><th scope="row">Android developer artifact</th><td><code>PocketMic-v0.1.4-release-unsigned.apk</code><br>Unsigned; not presented as the consumer install button</td></tr><tr><th scope="row">Windows receiver</th><td><code>PocketMicReceiver-win-x64.zip</code><br>Self-contained x64 application, not an installer</td></tr><tr><th scope="row">Checksums</th><td>{ext(SUMS,'SHA256SUMS.txt')}</td></tr></tbody></table><div class="callout warning"><strong>What this release does not establish.</strong><p>It does not provide a production-signed Android APK or a Windows installer. Its notes explicitly leave end-to-end hardware, Wi-Fi, Windows audio-driver, and VB-CABLE acceptance to physical-device testing.</p></div><p class="muted">No date is promised here for a bundled PocketMic virtual microphone driver, store distribution, automatic updates, or other operating systems.</p>{p.source_note()}</div></section>'''

# -------------------------------- PRIVACY / EXISTING POLICY ALIAS
privacy_intro='The native apps and the marketing website have different boundaries. This page explains the supplied product’s local-audio design and the behaviour of this website build.'
for key in ['privacy','policy']:
    p=page(key,'Privacy and terms — PocketMic LAN','PocketMic app privacy boundaries, website scripts and functional session storage, external downloads, and the project’s MIT software licence.',noindex=(key=='policy'))
    p.body=p.hero('Privacy & terms','Know where<br><span class="accent">the audio goes.</span>',privacy_intro,label='Privacy & terms')
    p.body+=f'''<section class="page-section"><div class="wrap narrow prose"><p class="policy-date">Website policy draft for this build · 9 September 2026</p><h2 style="font-size:2rem">The PocketMic app connection</h2><p>PocketMic is designed to send microphone audio from Android to a Windows receiver on a trusted private network. No PocketMic account or cloud relay is required for that local connection. The supplied app policy states that the apps do not send telemetry.</p><p>Pairing and connection settings are stored locally by the native apps. The supplied policy describes encrypted pairing-key storage on Android and a local receiver settings file on Windows. Review diagnostic exports before sharing; never publish the pairing key or QR code.</p><p>The local transport boundary ends at Windows. Discord, Teams, OBS, Zoom, or another destination app may send, process, stream, or record the audio according to its own settings and policies. “No cloud relay” does not make an online meeting private to your LAN.</p><h2 style="font-size:2rem">This website build</h2><p>The delivered site uses self-hosted CSS, JavaScript, and image files. It does not include Google Analytics, advertising tags, external badge requests, third-party fonts, embedded donation widgets, microphone access, or tracking pixels. It does not ask for your pairing key or device IP address.</p><p>The setup checklist saves your checked steps in <code>sessionStorage</code> only after you interact. The data stays in that tab’s session and can be cleared using “Reset this checklist.” No account, identifier, audio recording, or device details are stored by that feature.</p><p>Campaign parameters may be carried between internal page links, after restricting their format and length. The JavaScript emits local browser events describing link clicks and self-reported checklist actions. No analytics service receives those events from this build.</p><p>The hosting provider may process ordinary server-request logs. Server/CDN logging, injected host scripts, retention periods, and any future analytics integration must be reviewed by the site operator before this draft is published as the final policy.</p><h2 style="font-size:2rem">External destinations</h2><p>GitHub hosts release downloads and source code. VB-Audio hosts its separate audio driver. Official app-support pages and the optional Buy Me a Coffee link are external sites with their own terms. No third-party widget is loaded merely by opening this website.</p><h2 style="font-size:2rem">Software licence and support boundary</h2><p>The supplied project identifies PocketMic software as MIT licensed. The software is provided under its licence terms without a warranty. Consult the licence in the pinned source; this marketing page is not a separate warranty or service-level commitment.</p><p>Use PocketMic only on a trusted private LAN. Do not port-forward the receiver. Encryption is a transport property, not an independent security certification. Test the software on your own devices before relying on it.</p><p>VB-CABLE is a separate third-party product with its own donationware licensing and installation requirements. PocketMic is not affiliated with or endorsed by Discord, OBS, Microsoft, Zoom, or VB-Audio. Those names identify possible audio destinations or setup dependencies.</p><h2 style="font-size:2rem">Questions or corrections</h2><p>{ext(REPO+'/issues','Open an issue on the project’s GitHub repository')} without posting secrets or sensitive diagnostic details.</p></div></section>'''

# -------------------------------- OUTPUT

def render(p: Page, base_url: str) -> str:
    canonical = urljoin(base_url, clean_route(PATHS['privacy'] if p.key=='policy' else p.path))
    nav_data=[('home','Use cases','#use-cases'),('setup','Setup guide',''),('downloads','Downloads',''),('engineering','Technical','')]
    nav=''.join(f'<a href="{p.href(k,s)}"'+(' aria-current="page"' if p.key==k and not s else '')+f'>{label}</a>' for k,label,s in nav_data)
    mobile=f'<div class="mobile-cta"><p><strong>Android + Windows</strong>Free · Open source · v0.1.4</p>{p.link("downloads","Get the apps "+icon("arrow"),"btn primary")}</div>' if p.mobile_cta else ''
    schema={'@context':'https://schema.org','@type':'WebPage','name':p.title+' | PocketMic LAN','description':p.description,'url':canonical,'isPartOf':{'@type':'WebSite','name':'PocketMic LAN','url':base_url}}
    if p.key=='home':
        schema={'@context':'https://schema.org','@type':'SoftwareApplication','name':'PocketMic LAN','operatingSystem':'Android 8 or later; Windows 11 x64','applicationCategory':'MultimediaApplication','description':p.description,'url':base_url,'softwareVersion':'0.1.4','license':'https://opensource.org/license/mit','author':{'@type':'Person','name':'Ryan Spice-Finnie'},'downloadUrl':RELEASE}
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="dark"><meta name="theme-color" content="#101614"><meta name="referrer" content="strict-origin-when-cross-origin"><title>{E(p.title)} | PocketMic LAN</title><meta name="description" content="{E(p.description,quote=True)}"><link rel="canonical" href="{E(canonical,quote=True)}">{'<meta name="robots" content="noindex,follow">' if p.noindex else ''}
<meta property="og:type" content="website"><meta property="og:site_name" content="PocketMic LAN"><meta property="og:title" content="{E(p.title,quote=True)}"><meta property="og:description" content="{E(p.description,quote=True)}"><meta property="og:url" content="{E(canonical,quote=True)}"><meta property="og:image" content="{urljoin(base_url,'assets/social/'+(p.key if p.key in ['discord','obs','meetings','engineering'] else 'launch')+'-1200x630.png')}"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="PocketMic: Android to Windows microphone, encrypted over your local network"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{E(p.title,quote=True)}"><meta name="twitter:description" content="{E(p.description,quote=True)}"><meta name="twitter:image" content="{urljoin(base_url,'assets/social/'+(p.key if p.key in ['discord','obs','meetings','engineering'] else 'launch')+'-1200x630.png')}">
<link rel="icon" type="image/svg+xml" href="{p.asset('favicon.svg')}"><link rel="stylesheet" href="{p.asset('site.css')}"><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script><script src="{p.asset('site.js')}" defer></script></head>
<body data-root="{p.root}" data-page="{p.key}" class="{'has-mobile-cta' if p.mobile_cta else ''}"><a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="wrap header-row">{brand(p)}<nav class="main-nav" id="primary-nav" aria-label="Primary navigation">{nav}</nav><div class="header-cta">{p.link('downloads','Get the apps '+icon('external'),'btn primary small')}</div><button type="button" class="nav-toggle" aria-controls="primary-nav" aria-expanded="false" aria-label="Open navigation">{icon('menu')}</button></div></header><main id="main">{p.body}</main>{footer(p)}{mobile}<div class="toast" id="status-message" role="status" aria-live="polite"></div><dialog class="media-modal" id="screenshot-dialog" aria-label="App screenshot"><button type="button" class="btn small" data-close-dialog>Close {icon('close')}</button><img alt=""></dialog></body></html>'''

def main() -> None:
    parser=argparse.ArgumentParser()
    parser.add_argument('--base-url',default='https://canopydigital.ca/sites/pocketmic-lan/')
    args=parser.parse_args()
    base=args.base_url.rstrip('/')+'/'
    if not base.startswith(('https://','http://')): raise SystemExit('Base URL must be an absolute http(s) URL.')
    SITE.mkdir(parents=True,exist_ok=True)
    (SITE/'assets').mkdir(exist_ok=True)
    for asset in ['site.css','site.js']:
        (SITE/'assets'/asset).write_text((ROOT/'src'/asset).read_text(encoding='utf-8'),encoding='utf-8')
    (SITE/'assets/favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 40 40"><rect width="40" height="40" rx="11" fill="#88efbe"/><g fill="none" stroke="#102b1e" stroke-width="2.4" stroke-linecap="round"><rect x="15" y="7" width="10" height="17" rx="5"/><path d="M10 18v3a10 10 0 0 0 20 0v-3M20 31v4M15 35h10"/></g></svg>',encoding='utf-8')
    routes=[]
    for p in PAGES:
        target=SITE/p.path; target.parent.mkdir(parents=True,exist_ok=True)
        target.write_text(render(p,base),encoding='utf-8')
        routes.append({'key':p.key,'path':p.path,'url':urljoin(base,clean_route(p.path)),'title':p.title,'noindex':p.noindex})
    sitemap='<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'  <url><loc>{E(r["url"])}</loc></url>\n' for r in routes if not r['noindex'])+'</urlset>\n'
    (SITE/'sitemap.xml').write_text(sitemap,encoding='utf-8')
    (SITE/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+urljoin(base,'sitemap.xml')+'\n',encoding='utf-8')
    (SITE/'routes.json').write_text(json.dumps(routes,indent=2),encoding='utf-8')
    (SITE/'release.json').write_text(json.dumps({'version':TAG,'checkedOn':'2026-09-09','releaseUrl':RELEASE,'android':{'url':APK,'sha256':APK_HASH,'bytes':36423603,'signing':'debug-signed'},'windows':{'url':WIN,'sha256':WIN_HASH,'bytes':68123710,'packaging':'self-contained ZIP'}},indent=2),encoding='utf-8')
    print(f'Built {len(PAGES)} pages into {SITE}')

if __name__=='__main__': main()
